import { useAtomValue } from "jotai";
import { AuthService } from "modules/auth/service/AuthService";
import { MatrixAtoms } from "modules/matrix-client/jotai";
import { NetworkAtoms } from "modules/network/jotai";
import { type FC, useEffect, useRef } from "react";
import { AppState, type AppStateStatus } from "react-native";

// How long sync keeps running after the app goes to the background
// before we stop it. iOS typically gives ~30s of background execution.
const BACKGROUND_SYNC_TIMEOUT_MS = 25_000;

export const SyncLifecycleProvider: FC = () => {
  const isOffline = useAtomValue(NetworkAtoms.isOffline);
  const syncService = useAtomValue(MatrixAtoms.syncService);
  const prevIsOfflineRef = useRef<boolean | null>(null);
  const stopSyncTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Start sync whenever a session is restored and sync service becomes available.
  // This covers launch paths that skip Splash's explicit startSync call (e.g. PIN screen).
  useEffect(() => {
    if (!syncService || !isOffline || AppState.currentState !== "active") {
      return;
    }
    AuthService.startSync();
  }, [syncService, isOffline, AppState.currentState]);

  // Network recovery: restart sync when coming back online
  useEffect(() => {
    if (prevIsOfflineRef.current === true && !isOffline) {
      AuthService.startSync();
    }
    prevIsOfflineRef.current = isOffline;
  }, [isOffline]);

  // AppState lifecycle: start sync on foreground, stop after background grace period
  useEffect(() => {
    const handleAppStateChange = (nextState: AppStateStatus) => {
      if (nextState === "active") {
        if (stopSyncTimerRef.current) {
          clearTimeout(stopSyncTimerRef.current);
          stopSyncTimerRef.current = null;
        }
        AuthService.startSync();
      } else if (nextState === "background") {
        stopSyncTimerRef.current = setTimeout(() => {
          AuthService.stopSync();
          stopSyncTimerRef.current = null;
        }, BACKGROUND_SYNC_TIMEOUT_MS);
      }
    };

    const subscription = AppState.addEventListener(
      "change",
      handleAppStateChange,
    );

    return () => {
      subscription.remove();
      if (stopSyncTimerRef.current) {
        clearTimeout(stopSyncTimerRef.current);
      }
    };
  }, []);

  return <></>;
};

